import React from 'react';
import { AbsoluteFill, useCurrentFrame, useVideoConfig, spring, interpolate } from 'remotion';
import { z } from 'zod';
import { CLAUDE, CLAUDE_FONT } from '../tokens/claude';
import { GH, GH_FONT } from '../tokens/github';

// FlowDiagram — generalizes GitHubCallChain into a positioned-node, real-edge,
// animated-flow diagram with bezier draw-on and a data pulse.
//
// skin:'github' → dark ground, GH.BLUE accent — matches CallChain exactly.
// skin:'claude' → cream ground, SPARK terracotta accent.
//
// Coordinate system: nodes positioned at (x, y) = top-left of card.
// Edges connect from port boundaries, not centers, via cubic bezier.
// Pulse uses parametric bezier formula (no DOM getPointAtLength).

// ─── schemas ─────────────────────────────────────────────────────────────────

export const flowNodeSchema = z.object({
  id:    z.string(),
  label: z.string(),
  sub:   z.string().optional(),
  icon:  z.string().optional(),
  tier:  z.enum(['client', 'edge', 'compute', 'data', 'network', 'generic']).optional(),
  type:  z.enum(['terminal', 'io', 'process', 'decision', 'store']).optional(),
  shape: z.enum(['stadium', 'parallelogram', 'rect', 'diamond', 'cylinder']).optional(),
  x:     z.number(),
  y:     z.number(),
  w:     z.number().optional(),
  h:     z.number().optional(),
  hi:         z.boolean().optional(),
  mono:       z.boolean().optional(),
  labelLines: z.array(z.string()).optional(),
  subLines:   z.array(z.string()).optional(),
});
export type FlowNode = z.infer<typeof flowNodeSchema>;

export const flowEdgeSchema = z.object({
  from:   z.string(),
  to:     z.string(),
  order:  z.number(),
  label:  z.string().optional(),
  kind:   z.enum(['request', 'reply', 'data', 'dep', 'flow', 'write', 'composition', 'aggregation', 'inherits']).default('⚠ SET IN BEAT SHEET'),
  dashed: z.boolean().optional(),
  head:   z.enum(['open', 'filledDiamond', 'openDiamond', 'hollowTriangle']).optional(),
});
export type FlowEdge = z.infer<typeof flowEdgeSchema>;

export const flowDiagramSchema = z.object({
  nodes:   z.array(flowNodeSchema),
  edges:   z.array(flowEdgeSchema),
  caption: z.string(),
  kicker:  z.string().optional(),
  skin:    z.enum(['claude', 'github']).default('⚠ SET IN BEAT SHEET'),
  pulse:   z.boolean().default(true),
  viewBox: z.object({ w: z.number(), h: z.number() }).default({ w: 1920, h: 1080 }),
});
export type FlowDiagramProps = z.infer<typeof flowDiagramSchema>;

// ─── geometry helpers ─────────────────────────────────────────────────────────

// Estimated node card dimensions for port routing.
// Visual cards use this as their fixed width; height is min (may grow with sub text).
export const NODE_W = 280;
export const NODE_H = 100;
const CTRL = 110; // bezier control-point tangent length

const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v));

// Cubic bezier — evaluates one axis at parameter t
function cubicBez(t: number, p0: number, p1: number, p2: number, p3: number): number {
  const u = 1 - t;
  return u * u * u * p0 + 3 * u * u * t * p1 + 3 * u * t * t * p2 + t * t * t * p3;
}

// Approximate bezier arc length via 24-sample chord summation (no DOM).
function approxBezLen(
  p0x: number, p0y: number, p1x: number, p1y: number,
  p2x: number, p2y: number, p3x: number, p3y: number,
  N = 24,

